const tabs = [...document.querySelectorAll('[data-solution]')];
function selectSolution(button) {
  const key = button.dataset.solution; const item = solutions[key];
  tabs.forEach(t => { const selected = t === button; t.setAttribute('aria-selected', String(selected)); t.tabIndex = selected ? 0 : -1; });
  document.querySelector('#solution-panel').setAttribute('aria-labelledby', button.id);
  document.querySelector('#solution-eyebrow').textContent = item.eyebrow;
  document.querySelector('#solution-title').innerHTML = item.title;
  document.querySelector('#solution-description').textContent = item.description;
  document.querySelector('#solution-features').replaceChildren(...item.features.map(text => { const li = document.createElement('li'); li.textContent = text; return li; }));
  document.querySelector('#diagram-source-a').textContent = item.sources[0]; document.querySelector('#diagram-source-b').textContent = item.sources[1];
  document.querySelector('#diagram-core-text').textContent = item.core;
  document.querySelector('#diagram-result').textContent = item.result; document.querySelector('#diagram-result-sub').textContent = item.sub;
}
tabs.forEach((t, i) => { t.addEventListener('click', () => selectSolution(t)); t.addEventListener('keydown', e => { let next; if (['ArrowDown','ArrowRight'].includes(e.key)) next = (i + 1) % tabs.length; if (['ArrowUp','ArrowLeft'].includes(e.key)) next = (i + tabs.length - 1) % tabs.length; if (e.key === 'Home') next = 0; if (e.key === 'End') next = tabs.length - 1; if (next !== undefined) { e.preventDefault(); selectSolution(tabs[next]); tabs[next].focus(); } }); });

